<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api'
import SalesOrderPrint from '../components/SalesOrderPrint.vue'
const rows=ref<any[]>([]),customers=ref<any[]>([]),products=ref<any[]>([]),categories=ref<any[]>([]),salespeople=ref<any[]>([]),loading=ref(false),dialog=ref(false),productId=ref<number|null>(null)
const productParentId=ref<number|null>(null),productCategoryId=ref<number|null>(null),productKeyword=ref(''),productLoading=ref(false),customerLoading=ref(false)
const detailDialog=ref(false),detailLoading=ref(false),detail=ref<any>(null)
const inlineDetail=ref<any>(null),inlineDetailLoading=ref(false),selectedOrderId=ref<number|null>(null)
const printSettingsDialog=ref(false)
const printSettings=reactive({formatVersion:2,companyName:'',paperSize:'CONTINUOUS_241_140' as 'CONTINUOUS_241_140'|'A4'|'A5',orientation:'landscape' as 'portrait'|'landscape',showPhone:true,showPrice:true,showRemark:true})
const editingId=ref<number|null>(null),editingVersion=ref(0),copySourceNo=ref(''),customerCode=ref('')
import { localToday } from '../utils/date'
const today=localToday()
const route=useRoute()
const routeValue=(value:unknown)=>Array.isArray(value)?String(value[0]||''):String(value||'')
const allDates=routeValue(route.query.dateScope)==='ALL'
const initialWorkflowStatus=routeValue(route.query.workflowStatus)
const query=reactive({keyword:'',status:'',workflowStatus:initialWorkflowStatus,dateFrom:allDates?'':today,dateTo:allDates?'':today,salesperson:'',recorder:'',settlementMethod:'',minAmount:undefined as number|undefined,maxAmount:undefined as number|undefined,sortBy:'date',sortDirection:'asc',page:1,pageSize:100}),form=reactive({orderDate:localToday(),customerId:null as number|null,salespersonId:null as number|null,settlementMethod:'Cash',remark:'',items:[] as any[]})
const normalizeSettlement=(value:string)=>value==='Credit'||value==='挂账'?'Credit':'Cash'
const total=computed(()=>form.items.reduce((s,x)=>s+Number(x.quantity||0)*Number(x.unitPrice||0),0))
const selectedCustomer=computed(()=>customers.value.find((x:any)=>x.id===form.customerId)||null)
async function load(){loading.value=true;try{const{data}=await api.get('/sales-orders',{params:query});rows.value=data.data.items}finally{loading.value=false}}
function handleSortChange({prop,order}:{prop:string,order:string}){query.sortBy=prop==='orderNo'?'documentNo':'date';query.sortDirection=order==='descending'?'desc':'asc';query.page=1;load()}
async function focusNewOrder(orderNo:string){await nextTick();const row=Array.from(document.querySelectorAll('.el-table__body-wrapper tbody tr')).find(x=>x.textContent?.includes(orderNo));if(!row)return;row.classList.add('newly-created-row');row.scrollIntoView({behavior:'smooth',block:'center'});window.setTimeout(()=>row.classList.remove('newly-created-row'),5000)}
function resetQuery(){Object.assign(query,{keyword:'',status:'',workflowStatus:'',dateFrom:'',dateTo:'',salesperson:'',recorder:'',settlementMethod:'',minAmount:undefined,maxAmount:undefined,sortBy:'date',sortDirection:'asc',page:1});load()}
const productChildren=computed(()=>categories.value.find(x=>x.id===productParentId.value)?.children||[])
async function searchCustomers(keyword=''){customerLoading.value=true;try{const term=keyword.trim();const{data}=await api.get('/customers',{params:{keyword:term,pageSize:100,enabled:true}});customers.value=data.data.items;if(term){const exact=customers.value.filter((c:any)=>normalizedCode(c.customerCode)===normalizedCode(term));if(exact.length===1)form.customerId=exact[0].id}}finally{customerLoading.value=false}}
function clearCustomerSelection(){form.customerId=null}
async function resolveCustomerCode(){const keyword=customerCode.value.trim();if(!keyword)return;await searchCustomers(keyword);const exactCode=customers.value.find((c:any)=>normalizedCode(c.customerCode)===normalizedCode(keyword));const exactContact=customers.value.filter((c:any)=>[c.phone,c.mobile].some((value:any)=>String(value||'').split(/[\s,，;；/]+/).some(part=>normalizedCode(part)===normalizedCode(keyword))));const matched=exactCode||(exactContact.length===1?exactContact[0]:customers.value.length===1?customers.value[0]:null);if(!matched){form.customerId=null;return ElMessage.warning(customers.value.length?`找到多个客户，请输入完整客户编号或电话`:`没有找到客户编号或电话“${keyword}”`)}form.customerId=matched.id;customerCode.value=matched.customerCode}
async function loadOptions(){const[,t,e]=await Promise.all([searchCustomers(),api.get('/product-categories/tree'),api.get('/employees',{params:{pageSize:100,enabled:true}})]);categories.value=t.data.data.filter((x:any)=>x.productCount>0&&x.code!=='016');const employeeRows=e.data.data.items||e.data.data;salespeople.value=employeeRows.filter((x:any)=>x.salesperson)}
function normalizedCode(value:any){return String(value??'').trim().toLocaleLowerCase()}
function nullableNumber(value:any){return value===''||value===null||value===undefined?null:Number(value)}
async function searchProducts(addExactMatch=false){productLoading.value=true;try{const keyword=productKeyword.value.trim();const categoryId=keyword?undefined:(productCategoryId.value||productParentId.value||undefined);const{data}=await api.get('/products',{params:{pageSize:100,enabled:true,saleable:true,categoryId,keyword}});products.value=data.data.items;const exact=keyword?products.value.filter((p:any)=>normalizedCode(p.skuCode)===normalizedCode(keyword)):[];productId.value=exact.length===1?exact[0].id:null;if(keyword&&!products.value.length)ElMessage.warning(`没有找到编号或名称包含“${keyword}”的可销售货品`);else if(addExactMatch&&exact.length===1)addProduct();else if(addExactMatch&&products.value.length>0)ElMessage.info('找到多个相近货品，请从结果中选择') }finally{productLoading.value=false}}
async function chooseProductParent(){productCategoryId.value=null;productId.value=null;products.value=[];await searchProducts()}
async function chooseProductCategory(){productId.value=null;products.value=[];await searchProducts()}
function blankItem(){return{skuId:null,skuCode:'',productName:'',packageSpec:null,packageCount:null,packageUnit:'',salesUnit:'',quantity:0,unitPrice:0,referencePrice:0,currentStock:null,remark:'',blank:true}}
function productItem(p:any){const referencePrice=Number(p.wholesalePrice||0);return{skuId:p.id,skuCode:p.skuCode,productName:p.productName,packageSpec:nullableNumber(p.packageSpec),packageCount:null,packageUnit:p.packageUnit||'',salesUnit:p.salesUnit,quantity:0,unitPrice:referencePrice,referencePrice,currentStock:Number(p.totalStock||0),remark:'',blank:false}}
function ensureBlankRow(){if(!form.items.some((x:any)=>!x.skuId))form.items.push(blankItem())}
async function openNew(){await loadOptions();if(!customers.value.length||!categories.value.length)return ElMessage.warning('请先录入至少一个有效客户和可销售货品');editingId.value=null;editingVersion.value=0;copySourceNo.value='';customerCode.value='';Object.assign(form,{orderDate:localToday(),customerId:null,salespersonId:null,settlementMethod:'Cash',remark:'',items:[blankItem()]});productId.value=null;productParentId.value=null;productCategoryId.value=null;productKeyword.value='';products.value=[];dialog.value=true;await nextTick();(document.querySelector('.customer-code-input input') as HTMLInputElement|null)?.focus()}
function addProduct(){const p=products.value.find(x=>x.id===productId.value);if(!p)return;if(form.items.some(x=>x.skuId===p.id))return ElMessage.warning(`${p.skuCode} 已在销售单中`);const referencePrice=Number(p.wholesalePrice||0);form.items.push({skuId:p.id,skuCode:p.skuCode,productName:p.productName,packageSpec:nullableNumber(p.packageSpec),packageCount:null,packageUnit:p.packageUnit||'',salesUnit:p.salesUnit,quantity:1,unitPrice:referencePrice,referencePrice,currentStock:Number(p.totalStock||0),remark:''});productId.value=null;productKeyword.value='';products.value=[]}
async function resolveProductCode(row:any,index:number){const code=String(row.skuCode||'').trim();if(!code)return;productLoading.value=true;try{const{data}=await api.get('/products',{params:{pageSize:100,enabled:true,saleable:true,keyword:code}});const matches=data.data.items||[];const exact=matches.find((p:any)=>normalizedCode(p.skuCode)===normalizedCode(code));if(!exact)return ElMessage.warning(`没有找到货品编号“${code}”`);if(form.items.some((x:any,i:number)=>i!==index&&x.skuId===exact.id))return ElMessage.warning(`${exact.skuCode} 已在销售单中`);Object.assign(row,productItem(exact));ensureBlankRow();await nextTick();(document.querySelectorAll('.quantity-input input')[index] as HTMLInputElement|null)?.focus()}finally{productLoading.value=false}}
async function focusPrice(index:number){await nextTick();(document.querySelectorAll('.unit-price-input input')[index] as HTMLInputElement|null)?.focus()}
async function finishItem(index:number){if(!form.items[index]?.skuId)return;ensureBlankRow();await nextTick();(document.querySelectorAll('.sku-code-input input')[index+1] as HTMLInputElement|null)?.focus()}
function salePriceClass(row:any){return Number(row.unitPrice)>Number(row.referencePrice)?'price-high':Number(row.unitPrice)>0&&Number(row.unitPrice)<Number(row.referencePrice)?'price-low':'price-equal'}
async function save(){const activeItems=form.items.filter((x:any)=>x.skuId);if(!form.customerId||!activeItems.length)return ElMessage.warning('请输入客户编号并添加货品');const invalidQuantity=activeItems.find(x=>!Number.isFinite(Number(x.quantity))||Number(x.quantity)<0.01||Math.abs(Number(x.quantity)*100-Math.round(Number(x.quantity)*100))>1e-8);if(invalidQuantity)return ElMessage.error(`数量必须不少于 0.01，且最多保留两位小数：${invalidQuantity.skuCode} ${invalidQuantity.productName}`);const negative=activeItems.find(x=>Number(x.unitPrice)<0);if(negative)return ElMessage.error(`单价不能为负数：${negative.skuCode} ${negative.productName}`);const low=activeItems.find(x=>Number(x.unitPrice)>0&&Number(x.unitPrice)<Number(x.referencePrice));if(low)return ElMessage.error(`售价过低：${low.skuCode} ${low.productName} 的单价不能低于参考价 ${Number(low.referencePrice).toFixed(2)}`);const payload={...form,items:activeItems};try{let created:any=null;if(editingId.value){await api.put(`/sales-orders/${editingId.value}`,{...payload,version:editingVersion.value});ElMessage.success('销售单草稿修改成功')}else{const{data}=await api.post('/sales-orders',payload);created=data.data}dialog.value=false;editingId.value=null;const wasCopy=!!copySourceNo.value;copySourceNo.value='';await load();if(created){await focusNewOrder(created.orderNo);ElMessage({type:'success',message:wasCopy?`已复制生成新销售单 ${created.orderNo}，已为你定位并高亮`:`销售单 ${created.orderNo} 创建成功，已为你定位并高亮`,duration:5000,showClose:true})}}catch(e:any){ElMessage.error(e?.response?.data?.message||'销售单保存失败，请稍后重试')}}
function fillFromDetail(d:any,orderDate=d.orderDate){if(!customers.value.some((x:any)=>x.id===d.customerId))customers.value.unshift({id:d.customerId,customerCode:d.customerCode,shortName:d.customerName,phone:d.customerPhone});customerCode.value=d.customerCode;Object.assign(form,{orderDate,customerId:d.customerId,salespersonId:d.salespersonId?Number(d.salespersonId):null,settlementMethod:normalizeSettlement(d.settlementMethod),remark:d.remark,items:[...d.items.map((x:any)=>({skuId:x.skuId,skuCode:x.skuCode,productName:[x.productName,x.specification,x.color].filter(Boolean).join(' '),packageSpec:nullableNumber(x.packageSpec),packageCount:nullableNumber(x.packageCount),packageUnit:x.packageUnit,salesUnit:x.salesUnit,quantity:Number(x.quantity),unitPrice:Number(x.unitPrice),referencePrice:Number(x.referencePrice),currentStock:Number(x.currentStock||0),remark:x.remark,blank:false})),blankItem()]})}
async function editOrder(row:any){await loadOptions();const{data}=await api.get(`/sales-orders/${row.id}`);const d=data.data;editingId.value=d.id;editingVersion.value=d.version;copySourceNo.value='';fillFromDetail(d);dialog.value=true}
async function copyOrder(row:any){await loadOptions();const{data}=await api.get(`/sales-orders/${row.id}`);editingId.value=null;editingVersion.value=0;copySourceNo.value=data.data.orderNo;fillFromDetail(data.data,localToday());dialog.value=true}
async function voidOrder(row:any){if(row.status!=='DRAFT'||row.printedAt)return ElMessage.warning('已审核或已打印的销售单不能更改');await ElMessageBox.confirm('真的要作废此单据吗','作废销售单',{confirmButtonText:'确定作废',cancelButtonText:'取消',type:'warning'});await api.post(`/sales-orders/${row.id}/void`,{version:row.version});ElMessage.success('已作废');await load()}
async function openDetail(row:any){detailLoading.value=true;detailDialog.value=true;try{const{data}=await api.get(`/sales-orders/${row.id}`);detail.value=data.data}finally{detailLoading.value=false}}
async function selectOrder(row:any){selectedOrderId.value=row.id;inlineDetailLoading.value=true;try{const{data}=await api.get(`/sales-orders/${row.id}`);if(selectedOrderId.value===row.id)inlineDetail.value=data.data}finally{if(selectedOrderId.value===row.id)inlineDetailLoading.value=false}}
async function printOrder(){if(!detail.value)return;await nextTick();let style=document.getElementById('sales-print-page-size') as HTMLStyleElement|null;if(!style){style=document.createElement('style');style.id='sales-print-page-size';document.head.appendChild(style)}const size=printSettings.paperSize==='CONTINUOUS_241_140'?'241mm 140mm':printSettings.paperSize;style.textContent=`@page { size: ${size} ${printSettings.orientation}; margin: ${printSettings.paperSize==='CONTINUOUS_241_140'?'5mm':'10mm'}; }`;window.print();try{await confirmPrintSuccess()}catch(e:any){if(e==='cancel'||e==='close')return;throw e}}
async function confirmPrintSuccess(){if(!detail.value)return;let reason='';if(detail.value.printedAt){const result=await ElMessageBox.prompt('请填写本次补打原因。补打只记录次数，不会再次扣库存。','确认补打成功',{inputValidator:v=>!!v||'必须填写补打原因',type:'warning'});reason=result.value}else{await ElMessageBox.confirm('仅在纸张已正常打印，或已经成功另存为 PDF 时确认。确认后立即扣减库存。','确认首次打印成功',{confirmButtonText:'确认成功并扣库存',cancelButtonText:'尚未打印',type:'warning'})}const{data}=await api.post(`/sales-orders/${detail.value.id}/confirm-print`,{version:detail.value.version,reason});ElMessage.success(data.data.firstPrint?'已确认打印并扣减库存':'补打已记录，未重复扣库存');const refreshed=await api.get(`/sales-orders/${detail.value.id}`);detail.value=refreshed.data.data;load()}
function loadPrintSettings(){try{const saved=JSON.parse(localStorage.getItem('sales-order-print-settings')||'{}');Object.assign(printSettings,saved);if(!saved.formatVersion){printSettings.paperSize='CONTINUOUS_241_140';printSettings.orientation='landscape'}}catch{/* 忽略旧版无效设置 */}}
function savePrintSettings(){localStorage.setItem('sales-order-print-settings',JSON.stringify(printSettings));printSettingsDialog.value=false;ElMessage.success('打印设置已保存')}
function csvCell(value:any){return `"${String(value??'').replaceAll('"','""')}"`}
function exportOrder(){if(!detail.value)return;const lines=[['编号','品名规格','数量','单位','单价','金额'],...detail.value.items.map((x:any)=>[x.skuCode,[x.productName,x.specification,x.color].filter(Boolean).join(' '),x.quantity,x.salesUnit,x.unitPrice,x.lineAmount])];downloadCsv(`${detail.value.orderNo}-销售单.csv`,lines)}
function downloadCsv(name:string,rows:any[][]){const blob=new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function statusText(row:any){if(row.status==='VOIDED')return '已作废';const tags=[];if(row.printedAt)tags.push('已打印');if(row.dispatchApproved)tags.push('已审核','已出车');else if(row.dispatched)tags.push('已录出车表');return tags.length?tags.join('、'):'已下单'}
function progressStep(row:any){if(row.status==='VOIDED')return -1;if(row.dispatchApproved)return 3;if(row.dispatched)return 2;if(row.printedAt)return 1;return 0}
function orderRowClassName({row}:{row:any}){return row.status==='VOIDED'?'voided-order-row':''}
function printKindText(kind:string){return kind==='FIRST_PRINT'?'首次打印':'补打'}
onMounted(()=>{loadPrintSettings();load()})
</script>
<template><section><div class="page-heading"><div><h1>销售单</h1><p>下单、库存检查、打印送货单与出车状态</p></div><el-button type="primary" @click="openNew">新建销售单</el-button></div>
<el-card><div class="advanced-search"><div class="search-row"><el-date-picker v-model="query.dateFrom" type="date" value-format="YYYY-MM-DD" placeholder="开始日期"/><span class="date-separator">至</span><el-date-picker v-model="query.dateTo" type="date" value-format="YYYY-MM-DD" placeholder="结束日期"/><el-input v-model="query.keyword" clearable placeholder="销售单号 / 客户编号 / 客户名称" @keyup.enter="load"/><el-input v-model="query.salesperson" clearable placeholder="业务员" @keyup.enter="load"/><el-button type="primary" @click="load">查询</el-button><el-button @click="resetQuery">清空条件</el-button></div><div class="search-row secondary"><el-input v-model="query.recorder" clearable placeholder="录入人" @keyup.enter="load"/><el-select v-model="query.settlementMethod" clearable placeholder="全部结算方式"><el-option label="现款" value="Cash"/><el-option label="挂账" value="Credit"/></el-select><el-input-number v-model="query.minAmount" :min="0" :precision="2" placeholder="最低金额" controls-position="right"/><span class="date-separator">至</span><el-input-number v-model="query.maxAmount" :min="0" :precision="2" placeholder="最高金额" controls-position="right"/></div><el-radio-group v-model="query.workflowStatus" class="workflow-filter" @change="load"><el-radio-button value="">全部</el-radio-button><el-radio-button value="UNPRINTED">未打印</el-radio-button><el-radio-button value="PRINTED">已打印</el-radio-button><el-radio-button value="UNDISPATCHED">未加入出车表</el-radio-button><el-radio-button value="DISPATCHED">已加入出车表</el-radio-button><el-radio-button value="APPROVED">已审核/已出车</el-radio-button></el-radio-group><el-checkbox v-model="query.status" true-value="VOIDED" false-value="" class="void-filter" @change="load">只看已作废</el-checkbox></div>
<el-table :data="rows" v-loading="loading" stripe highlight-current-row :row-class-name="orderRowClassName" :default-sort="{prop:'orderDate',order:'ascending'}" @sort-change="handleSortChange" @row-click="selectOrder" @row-dblclick="openDetail"><el-table-column prop="orderNo" label="销售单号" width="150" sortable="custom" :sort-orders="['ascending','descending']"/><el-table-column label="单据进度" width="300"><template #default="s"><div v-if="s.row.status==='VOIDED'" class="order-progress"><el-tag type="danger" effect="dark">已作废</el-tag></div><div v-else class="order-progress"><el-tag :type="progressStep(s.row)>=1?'warning':'info'" :effect="progressStep(s.row)>=1?'dark':'plain'">{{progressStep(s.row)>=1?'✓ 已打印':'未打印'}}</el-tag><el-tag :type="progressStep(s.row)>=2?'primary':'info'" :effect="progressStep(s.row)>=2?'dark':'plain'">{{progressStep(s.row)>=2?'✓ 已加入出车表':'未加入出车表'}}</el-tag><el-tag :type="progressStep(s.row)>=3?'success':'info'" :effect="progressStep(s.row)>=3?'dark':'plain'">{{progressStep(s.row)>=3?'✓ 已审核/出车':'未审核'}}</el-tag></div></template></el-table-column><el-table-column prop="orderDate" label="日期" width="110" sortable="custom" :sort-orders="['ascending','descending']"/><el-table-column prop="customerCode" label="客户编号" width="105"/><el-table-column prop="customerName" label="客户名称" min-width="180"/><el-table-column prop="totalAmount" label="总金额" width="105"/><el-table-column label="操作" width="265" fixed="right"><template #default="s"><el-button link type="primary" @click="openDetail(s.row)">打印预览</el-button><el-button link type="primary" @click="copyOrder(s.row)">复制开单</el-button><el-button v-if="s.row.status==='DRAFT'&&!s.row.printedAt" link type="primary" @click="editOrder(s.row)">修改</el-button><el-button v-if="s.row.status!=='VOIDED'&&!s.row.printedAt" link type="danger" @click="voidOrder(s.row)">作废</el-button></template></el-table-column></el-table><div class="inline-detail-panel" v-loading="inlineDetailLoading"><div class="inline-detail-heading"><div><strong>{{inlineDetail?`销售单 ${inlineDetail.orderNo} 的货物明细`:'单击上方销售单查看货物明细'}}</strong><span v-if="inlineDetail">双击上方销售单可打开完整详情</span></div><span v-if="inlineDetail">共 {{inlineDetail.items?.length||0}} 行，合计 ¥{{Number(inlineDetail.totalAmount||0).toFixed(2)}}</span></div><el-table v-if="inlineDetail" :data="inlineDetail.items" border max-height="300"><el-table-column prop="skuCode" label="编号" width="120"/><el-table-column label="品名规格" min-width="260"><template #default="s">{{[s.row.productName,s.row.specification,s.row.color].filter(Boolean).join(' ')}}</template></el-table-column><el-table-column prop="packageCount" label="件数" width="80"/><el-table-column prop="packageUnit" label="包装单位" width="100"/><el-table-column prop="quantity" label="数量" width="90"/><el-table-column prop="salesUnit" label="单位" width="80"/><el-table-column prop="unitPrice" label="单价" width="100"/><el-table-column prop="referencePrice" label="参考价" width="100"/><el-table-column prop="lineAmount" label="金额" width="110"/><el-table-column prop="remark" label="备注" min-width="130"/></el-table><el-empty v-else :image-size="64" description="请单击一张销售单"/></div></el-card>
<el-dialog v-model="dialog" :title="editingId?'修改销售单草稿':copySourceNo?`复制销售单 ${copySourceNo}`:'新建销售单'" width="1200px"><el-alert v-if="copySourceNo" title="已复制原单客户和货品；请核对数量、价格后保存，新单不会影响原销售单。" type="success" :closable="false" show-icon style="margin-bottom:14px"/><el-form label-width="82px"><el-row :gutter="12"><el-col :span="5"><el-form-item label="开单日期" required><el-date-picker v-model="form.orderDate" type="date" value-format="YYYY-MM-DD" :disabled="!!editingId" style="width:100%"/></el-form-item></el-col><el-col :span="6"><el-form-item label="客户编号" required><el-input v-model="customerCode" class="customer-code-input" placeholder="输入编号或电话后按 Enter" :loading="customerLoading" @input="clearCustomerSelection" @keyup.enter="resolveCustomerCode"/></el-form-item></el-col><el-col :span="7"><el-form-item label="客户名称"><el-input :model-value="selectedCustomer?.shortName||''" readonly placeholder="按 Enter 后自动显示"/></el-form-item></el-col><el-col :span="6"><el-form-item label="结算方式"><el-select v-model="form.settlementMethod"><el-option label="现款" value="Cash"/><el-option label="挂账" value="Credit"/></el-select></el-form-item></el-col></el-row><el-row :gutter="12"><el-col :span="16"><el-form-item label="电话"><el-input class="customer-phone-input" type="textarea" :autosize="{minRows:1,maxRows:2}" resize="none" :model-value="selectedCustomer?.phone||selectedCustomer?.mobile||''" readonly placeholder="按 Enter 后自动显示全部电话"/></el-form-item></el-col><el-col :span="8"><el-form-item label="业务员"><el-select v-model="form.salespersonId" clearable filterable placeholder="可选" style="width:100%"><el-option v-for="e in salespeople" :key="e.id" :label="`${e.code} ${e.name}`" :value="e.id"/></el-select></el-form-item></el-col></el-row>
<el-collapse class="optional-product-search"><el-collapse-item title="不知道货品编号？展开分类或名称查找" name="product-search"><el-form-item label="货品分类"><div class="product-filters"><el-select v-model="productParentId" clearable filterable placeholder="选择厂家/大类" @change="chooseProductParent"><el-option v-for="c in categories" :key="c.id" :label="`${c.code} ${c.name}（${c.productCount}种）`" :value="c.id"/></el-select><el-select v-model="productCategoryId" clearable filterable placeholder="第二步：选择小类" :disabled="!productParentId" @change="chooseProductCategory"><el-option v-for="c in productChildren" :key="c.id" :label="`${c.code} ${c.name}（${c.productCount}种）`" :value="c.id"/></el-select></div></el-form-item>
<el-form-item label="名称查找"><div class="product-picker"><el-input v-model="productKeyword" clearable placeholder="输入名称或部分编号" @keyup.enter="searchProducts(true)"/><el-button :loading="productLoading" @click="searchProducts(false)">全库查找</el-button><el-select v-model="productId" filterable placeholder="从结果中选择货品" :loading="productLoading"><el-option v-for="p in products" :key="p.id" :label="`${p.skuCode} ${p.productName}`" :value="p.id"/></el-select><el-button type="primary" plain :disabled="!productId" @click="addProduct">加入</el-button></div><div class="picker-hint">常用操作：直接在下方编号栏输入准确货品编号并按 Enter。</div></el-form-item></el-collapse-item></el-collapse></el-form>
<el-table :data="form.items" border class="sales-items-table"><el-table-column label="编号" width="105"><template #default="s"><el-input v-model="s.row.skuCode" class="sku-code-input" placeholder="输入编号" @keyup.enter="resolveProductCode(s.row,s.$index)"/></template></el-table-column><el-table-column prop="productName" label="品名规格" min-width="160"/><el-table-column label="现有库存" width="72"><template #default="s"><span :class="Number(s.row.currentStock)<Number(s.row.quantity)?'stock-warning':''">{{s.row.currentStock??'-'}}</span></template></el-table-column><el-table-column label="包装规格" width="82"><template #default="s"><el-input-number v-model="s.row.packageSpec" :disabled="!s.row.skuId" :min="0" :precision="2" :controls="false"/></template></el-table-column><el-table-column label="件数" width="68"><template #default="s"><el-input-number v-model="s.row.packageCount" :disabled="!s.row.skuId" :min="0" :precision="2" :controls="false"/></template></el-table-column><el-table-column label="包装单位" width="80"><template #default="s"><el-input v-model="s.row.packageUnit" :disabled="!s.row.skuId"/></template></el-table-column><el-table-column label="数量" width="86"><template #default="s"><el-input-number v-model="s.row.quantity" class="quantity-input" :disabled="!s.row.skuId" :precision="2" :controls="false" @keyup.enter="focusPrice(s.$index)"/></template></el-table-column><el-table-column prop="salesUnit" label="单位" width="52"/><el-table-column label="单价" width="90"><template #default="s"><el-input-number v-model="s.row.unitPrice" class="unit-price-input" :disabled="!s.row.skuId" :precision="2" :controls="false" :class="salePriceClass(s.row)" @keyup.enter="finishItem(s.$index)"/></template></el-table-column><el-table-column label="参考价" width="72"><template #default="s">{{s.row.skuId?Number(s.row.referencePrice).toFixed(2):'—'}}</template></el-table-column><el-table-column label="金额" width="82"><template #default="s">{{s.row.skuId?(s.row.quantity*s.row.unitPrice).toFixed(2):'—'}}</template></el-table-column><el-table-column label="备注" width="90"><template #default="s"><el-input v-model="s.row.remark" :disabled="!s.row.skuId" @keyup.enter="finishItem(s.$index)"/></template></el-table-column><el-table-column label="操作" width="52"><template #default="s"><el-button v-if="s.row.skuId" link type="danger" @click="form.items.splice(s.$index,1);ensureBlankRow()">删除</el-button></template></el-table-column></el-table>
<div class="order-total">合计：¥ {{total.toFixed(2)}}</div><el-form label-width="90px"><el-form-item label="备注"><el-input v-model="form.remark"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">{{editingId?'保存修改':copySourceNo?'生成新草稿':'保存草稿'}}</el-button></template></el-dialog>
<el-dialog v-model="detailDialog" :title="`销售单打印预览 ${detail?.orderNo||''}`" width="980px" append-to-body class="sales-detail-dialog"><div class="print-preview-toolbar"><div><el-tag v-if="detail?.printedAt" type="warning">已打印 {{detail.printCount}} 次</el-tag><el-tag v-if="detail?.dispatchApproved" type="success">已审核、已出车</el-tag></div><el-button @click="printSettingsDialog=true">打印设置</el-button></div><el-alert v-if="detail" :title="`录入：${detail.createdByName} ${String(detail.createdAt).replace('T',' ')}；修改：${detail.updatedByName} ${String(detail.updatedAt).replace('T',' ')}；打印：${detail.printedByName||'未打印'} ${detail.printedAt?String(detail.printedAt).replace('T',' '):''}；审核：${detail.dispatchApprovedByName||'未审核'} ${detail.dispatchApprovedAt?String(detail.dispatchApprovedAt).replace('T',' '):''}`" type="info" :closable="false"/><el-collapse v-if="detail?.printHistory?.length" class="print-history"><el-collapse-item :title="`打印记录（${detail.printHistory.length} 次）`" name="history"><el-table :data="detail.printHistory" size="small" border><el-table-column prop="printNo" label="次数" width="70"/><el-table-column label="类型" width="100"><template #default="s"><el-tag :type="s.row.printKind==='FIRST_PRINT'?'success':'warning'" size="small">{{printKindText(s.row.printKind)}}</el-tag></template></el-table-column><el-table-column prop="printedByName" label="打印人" width="120"/><el-table-column label="打印时间" width="190"><template #default="s">{{String(s.row.printedAt).replace('T',' ')}}</template></el-table-column><el-table-column label="补打原因" min-width="220"><template #default="s">{{s.row.reason||'—'}}</template></el-table-column></el-table></el-collapse-item></el-collapse><div v-loading="detailLoading" class="sales-print-host"><SalesOrderPrint v-if="detail" :detail="detail" type="delivery" :settings="printSettings"/></div><template #footer><el-button @click="detailDialog=false">关闭</el-button><el-button :disabled="!detail" @click="exportOrder">导出明细 CSV</el-button><el-button :disabled="!detail||detail.status==='VOIDED'" @click="printOrder">打开系统打印</el-button><el-button type="success" :disabled="!detail||detail.status==='VOIDED'" @click="confirmPrintSuccess">{{detail?.printedAt?'确认补打成功':'确认打印成功并扣库存'}}</el-button></template></el-dialog>
<el-dialog v-model="printSettingsDialog" title="送货单打印设置" width="560px" append-to-body><el-form label-width="120px"><el-form-item label="公司抬头"><el-input v-model="printSettings.companyName" clearable placeholder="留空则不显示"/></el-form-item><el-form-item label="纸张"><el-select v-model="printSettings.paperSize"><el-option label="针式连续纸 241×140mm（推荐）" value="CONTINUOUS_241_140"/><el-option label="A4（备用）" value="A4"/><el-option label="A5（备用）" value="A5"/></el-select></el-form-item><el-form-item label="方向"><el-radio-group v-model="printSettings.orientation"><el-radio value="landscape">横向</el-radio><el-radio value="portrait">纵向</el-radio></el-radio-group></el-form-item><el-form-item label="打印内容"><el-checkbox v-model="printSettings.showPhone">客户电话</el-checkbox><el-checkbox v-model="printSettings.showPrice">单价和金额</el-checkbox><el-checkbox v-model="printSettings.showRemark">备注</el-checkbox></el-form-item></el-form><el-alert title="公司默认使用针式连续纸。首次确认打印成功会扣库存；补打不会重复扣库存。" type="info" :closable="false"/><template #footer><el-button @click="printSettingsDialog=false">取消</el-button><el-button type="primary" @click="savePrintSettings">保存设置</el-button></template></el-dialog>
</section></template>
